
(function(){
 const shareSvg='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="18" cy="5" r="2.5"></circle><circle cx="6" cy="12" r="2.5"></circle><circle cx="18" cy="19" r="2.5"></circle><path d="M8.2 10.8 15.8 6.3M8.2 13.2l7.6 4.5"></path></svg>';
 const cartSvg='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 4h2l2.2 10.1a2 2 0 0 0 2 1.6h7.9a2 2 0 0 0 2-1.6L21 7H6"></path><circle cx="10" cy="20" r="1.5"></circle><circle cx="18" cy="20" r="1.5"></circle></svg>';
 const heartSvg='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20.4 4.3 13A5.2 5.2 0 0 1 12 6a5.2 5.2 0 0 1 7.7 7L12 20.4Z"></path></svg>';
 function favProducts(){return [...liftFavorites].map(id=>PRODUCTS.find(p=>Number(p.id)===Number(id))).filter(Boolean)}
 function syncFavCount(){const n=liftFavorites.size;document.querySelectorAll('.liftFavCount').forEach(x=>x.textContent=n);const b=document.getElementById('liftShareFavBtn');if(b)b.disabled=!n}
 window.renderLiftFavorites=function(){const body=document.getElementById('liftFavBody');if(!body)return;const ps=favProducts();body.innerHTML=ps.length?ps.map(p=>`<div class="liftFavLine"><img src="${p.image||''}" alt=""><div><div class="liftFavName">${typeof esc==='function'?esc(p.name):p.name}</div><div class="liftFavMeta">${typeof esc==='function'?esc(p.brand||''):p.brand||''}</div><div class="liftFavPrice${savingOf(p)?' promoPrice':''}">${savingOf(p)?`<span class="oldPrice">${fmt(compareAtOf(p))}</span> `:''}${typeof fmt==='function'?fmt(priceOf(p)):'$'+Number(p.price||0).toLocaleString('es-CO')}</div></div><div class="liftFavActions"><button class="liftFavMini" title="Compartir" onclick="shareLiftProductImage(${Number(p.id)})">${shareSvg}</button><button class="liftFavMini" title="Agregar al carrito" onclick="${((typeof flavorsFor==='function'&&flavorsFor(p.id).length)||(Array.isArray(p.pdfFlavors)&&p.pdfFlavors.length))?`openLiftProductById(${Number(p.id)})`:`add(${Number(p.id)})`}">${cartSvg}</button><button class="liftFavMini" title="Quitar de favoritos" onclick="toggleLiftFavorite(${Number(p.id)});renderLiftFavorites();syncLiftFavoriteButtons()">×</button></div></div>`).join(''):'<div class="empty">Todavía no tienes favoritos.</div>';syncFavCount()}
 window.syncLiftFavoriteButtons=function(){document.querySelectorAll('.liftCardFav').forEach(btn=>{const m=(btn.getAttribute('onclick')||'').match(/toggleLiftFavorite\((\d+)/);if(m)btn.classList.toggle('active',liftFavorites.has(Number(m[1])))})}
 const oldToggle=window.toggleLiftFavorite||toggleLiftFavorite;window.toggleLiftFavorite=function(id,btn){oldToggle(id,btn);syncFavCount();if(document.getElementById('liftFavOff')?.classList.contains('open'))renderLiftFavorites()}
 function addHeaderIcons(){const bar=document.querySelector('.top .bar');if(!bar)return;let cart=bar.querySelector('.cartDesktop');if(cart){cart.innerHTML=cartSvg+'<span id="count" class="badge">0</span>';cart.setAttribute('aria-label','Abrir carrito');cart.setAttribute('title','Carrito');cart.classList.add('liftHeaderIcon')}
  if(!document.getElementById('liftFavHeaderBtn')){const b=document.createElement('button');b.id='liftFavHeaderBtn';b.className='liftHeaderIcon';b.type='button';b.title='Favoritos';b.setAttribute('aria-label','Abrir favoritos');b.innerHTML=heartSvg+'<span class="liftIconCount liftFavCount">0</span>';b.onclick=()=>{renderLiftFavorites();openOff('liftFavOff')};if(cart)bar.insertBefore(b,cart);else bar.appendChild(b)}syncFavCount()}
 const oldOpen=window.openOff;window.openOff=function(id){oldOpen(id);if(id==='liftFavOff')renderLiftFavorites()}
 function injectCartShare(){const foot=document.querySelector('#cart .cartfoot');if(!foot||foot.querySelector('.liftCartShareWrap'))return;const w=document.createElement('div');w.className='liftCartShareWrap';w.innerHTML=`<button class="liftCartShareBtn" onclick="shareLiftCartImage()">${shareSvg}<span>Compartir carrito como imagen</span></button>`;foot.insertBefore(w,foot.firstChild)}
 const oldRenderCart=window.renderCart;window.renderCart=function(){const r=oldRenderCart.apply(this,arguments);injectCartShare();return r}
 function wrapLines(ctx,text,maxWidth,maxLines){const words=String(text||'').split(/\s+/);const lines=[];let line='';for(const word of words){const test=line?line+' '+word:word;if(ctx.measureText(test).width>maxWidth&&line){lines.push(line);line=word;if(lines.length===maxLines-1)break}else line=test}if(line&&lines.length<maxLines)lines.push(line);return lines}
 async function makeListImage(title,rows,showQty){if(!rows.length){liftShareToast('No hay productos para compartir');return}liftShareToast('Creando imagen…');const W=1080,rowH=210,H=Math.min(8000,230+rows.length*rowH+130);const c=document.createElement('canvas');c.width=W;c.height=H;const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,W,H);ctx.fillStyle='#0b0b0b';ctx.fillRect(0,0,W,125);ctx.fillStyle='#fff';ctx.font='700 40px Poppins,Arial';ctx.fillText('LIFT NUTRIENTES',55,55);ctx.font='500 25px Poppins,Arial';ctx.fillText(title,55,95);let y=160;for(const row of rows){const p=row.p||row;const q=row.q||1;ctx.strokeStyle='#e7e7e7';ctx.beginPath();ctx.moveTo(55,y+rowH-12);ctx.lineTo(1025,y+rowH-12);ctx.stroke();try{const img=await liftLoadShareImage(p.image);if(img){const r=Math.min(145/img.width,145/img.height);ctx.drawImage(img,60+(145-img.width*r)/2,y+10+(145-img.height*r)/2,img.width*r,img.height*r)}}catch(e){}ctx.fillStyle='#777';ctx.font='500 20px Poppins,Arial';ctx.fillText(String(p.brand||'').toUpperCase(),235,y+35);ctx.fillStyle='#111';ctx.font='600 27px Poppins,Arial';const lines=wrapLines(ctx,p.name,720,2);lines.forEach((ln,i)=>ctx.fillText(ln,235,y+75+i*35));ctx.font='700 29px Poppins,Arial';const price=typeof fmt==='function'?fmt(priceOf(p)*q):'$'+Number((p.price||0)*q).toLocaleString('es-CO');ctx.fillText(price,235,y+158);if(showQty&&q>1){ctx.font='500 20px Poppins,Arial';ctx.fillStyle='#666';ctx.fillText('Cantidad: '+q,780,y+158)}y+=rowH}ctx.fillStyle='#666';ctx.font='500 20px Poppins,Arial';ctx.fillText('Precios sujetos a disponibilidad.',55,H-55);const blob=await new Promise(res=>c.toBlob(res,'image/png',.94));if(!blob)throw new Error('blob');const file=new File([blob],`lift-${title.toLowerCase().replace(/[^a-z0-9]+/g,'-')}.png`,{type:'image/png'});await window.liftShareGeneratedImage(blob,file,title)}
 window.shareLiftFavoritesImage=()=>makeListImage('Favoritos',favProducts(),false).catch(e=>{console.error(e);liftShareToast('No se pudo generar la imagen')});
 window.shareLiftCartImage=()=>makeListImage('Tu pedido',typeof items==='function'?items():[],true).catch(e=>{console.error(e);liftShareToast('No se pudo generar la imagen')});
 document.addEventListener('DOMContentLoaded',()=>{addHeaderIcons();injectCartShare();syncFavCount();syncLiftFavoriteButtons()});setTimeout(()=>{addHeaderIcons();injectCartShare();syncFavCount()},100);
})();
